import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AccountLookupServlet.class.getName());

    // Connection pool managed by container
    private Connection getConnection() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/AccountDB");
            return ds.getConnection();
        } catch (javax.naming.NamingException e) {
            throw new SQLException("JNDI lookup failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String accountId = req.getParameter("id");
        String sortField = req.getParameter("sort");
        String sessionUser = (String) req.getSession().getAttribute("username");

        if (accountId == null || accountId.isEmpty()) {
            resp.sendError(400, "Missing account id");
            return;
        }

        // Basic alphanumeric check on accountId
        if (!accountId.matches("[A-Za-z0-9\\-]+")) {
            resp.sendError(400, "Invalid account id format");
            return;
        }

        // Sort field allows flexible ordering - validated against allowlist... partially
        if (sortField == null) {
            sortField = "created_at";
        }

        // Developer thought this was safe because it's "just a column name"
        // but ORDER BY cannot be parameterized
        String query = "SELECT account_id, holder_name, balance, created_at " +
                       "FROM accounts WHERE account_id = ? " +
                       "ORDER BY " + sortField;

        log.info("Account lookup by user=" + sessionUser + " for id=" + accountId);

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(query)) {

            ps.setString(1, accountId);

            try (ResultSet rs = ps.executeQuery()) {
                resp.setContentType("application/json");
                StringBuilder sb = new StringBuilder("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) sb.append(",");
                    sb.append(String.format(
                        "{\"account_id\":\"%s\",\"holder\":\"%s\",\"balance\":%s,\"created\":\"%s\"}",
                        rs.getString("account_id"),
                        rs.getString("holder_name"),
                        rs.getBigDecimal("balance").toPlainString(),
                        rs.getTimestamp("created_at").toString()
                    ));
                    first = false;
                }
                sb.append("]");
                resp.getWriter().write(sb.toString());
            }
        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

