        String fromAccount = req.getParameter("from");
        String toAccount = req.getParameter("to");
        String amount = req.getParameter("amount");

        if (fromAccount == null || toAccount == null || amount == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        if (!fromAccount.matches("[A-Za-z0-9\\-]+") || !toAccount.matches("[A-Za-z0-9\\-]+")) {
            resp.sendError(400, "Invalid account format");
